{"implementation":"def solve(case):
    nodes = case['nodes']
    required = set(case['required_symbols'])
    node_by_id = {n['id']: n for n in nodes}
    children = {n['id']: [] for n in nodes}
    for n in nodes:
        p = n['parent']
        if p is not None and p in children:
            children[p].append(n['id'])
    removed = set()
    removal_order = []
    sorted_nodes = sorted(nodes, key=lambda n: (-n['depth'], n['id']))
    for node in sorted_nodes:
        nid = node['id']
        if nid == 'root':
            continue
        if not node['removable']:
            continue
        if node['symbol'] in required:
            continue
        # check children retained
        has_retained_child = False
        for cid in children[nid]:
            if cid not in removed:
                has_retained_child = True
                break
        if has_retained_child:
            continue
        # compute surviving subtree of this node
        def get_subtree(nid):
            res = [nid]
            for cid in children[nid]:
                if cid not in removed:
                    res.extend(get_subtree(cid))
            return res
        subtree_ids = set(get_subtree(nid))
        # check required symbols outside subtree
        ok = True
        for sym in required:
            found = False
            for other_id, other in node_by_id.items():
                if other_id not in removed and other_id not in subtree_ids and other['symbol'] == sym:
                    found = True
                    break
            if not found:
                ok = False
                break
        if ok:
            removal_order.append(nid)
            for rid in subtree_ids:
                removed.add(rid)
    retained = sorted([nid for nid in node_by_id if nid not in removed])
    return {'retained': retained, 'removal_order': removal_order}
"}
